export function buildReceipt({fileName:s,sha256:a,report:e,graph:n,seed:l,post:t,destroyKey:i}){return{schema:"ticket-v1",generated:new Date().toISOString().slice(0,19).replace("T"," ")+" UTC",file:{name:s,sha256:a},summary:{systems:e.totals.systems,events:e.totals.events,regions:e.totals.regions,named_planets:e.totals.named_planets,galaxies:e.totals.galaxies,period:e.period,birth:e.birth,teleports:e.trajectory.teleports.length,bases:e.trajectory.bases.length,beats:n.beats.map(g=>g.type)},seed:l,destroy_key:i??null,post_encoding:t?t.encoding:null,post_bytes:t?JSON.stringify(t).length:0}}
